draw:
var g = 9.8;
var w = Math.sqrt(p.k / p.mass);
var x0 = p.mass * g / p.k;
var A = p.amp;
var y = x0 + A * Math.cos(w * t);
var span = x0 + A + 0.03;
var pxPerM = (H * 0.46) / span;
var cx = W * 0.42;
var ceil = H * 0.10;
var natural = H * 0.20;
var yNat = ceil + natural;
var yEq = ceil + natural + x0 * pxPerM;
var yBlk = ceil + natural + y * pxPerM;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

// ceiling
ctx.fillStyle = C.faint;
ctx.fillRect(cx - W * 0.18, ceil - 8, W * 0.36, 8);

// spring coils from ceiling to block
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(cx, ceil);
var n = 14;
var top = ceil;
var bot = yBlk - 16;
for (var i = 1; i <= n; i++) {
  var yy = top + (bot - top) * i / n;
  var dx = (i % 2 === 0 ? -12 : 12) * (i === n ? 0 : 1);
  ctx.lineTo(cx + dx, yy);
}
ctx.lineTo(cx, bot);
ctx.stroke();

// natural-length marker
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx - W * 0.22, yNat); ctx.lineTo(cx + W * 0.30, yNat); ctx.stroke();
// equilibrium marker
ctx.beginPath(); ctx.moveTo(cx - W * 0.22, yEq); ctx.lineTo(cx + W * 0.30, yEq); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.rule;
ctx.fillText("natural length", cx + W * 0.14, yNat - 4);
ctx.fillText("equilibrium", cx + W * 0.14, yEq - 4);

// extension arrow
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
var ax = cx - W * 0.20;
ctx.beginPath(); ctx.moveTo(ax, yNat); ctx.lineTo(ax, yEq); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ax - 4, yEq - 6); ctx.lineTo(ax, yEq); ctx.lineTo(ax + 4, yEq - 6); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("x0 = mg/k", ax - 6, (yNat + yEq) / 2 - 4);

// block
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(cx - 18, yBlk - 16, 36, 32, 4); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("m", cx - 4, yBlk + 4);

// force arrows on the block
var Fs = p.k * y;
var Fw = p.mass * g;
var fScale = (H * 0.16) / Math.max(Fs, Fw);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
var bx = cx + 34;
ctx.beginPath(); ctx.moveTo(bx, yBlk); ctx.lineTo(bx, yBlk - Fs * fScale); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx - 4, yBlk - Fs * fScale + 7); ctx.lineTo(bx, yBlk - Fs * fScale); ctx.lineTo(bx + 4, yBlk - Fs * fScale + 7); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("kx = " + Fs.toFixed(1) + " N", bx + 6, yBlk - Fs * fScale + 4);

ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.moveTo(bx, yBlk); ctx.lineTo(bx, yBlk + Fw * fScale); ctx.stroke();
ctx.beginPath(); ctx.moveTo(bx - 4, yBlk + Fw * fScale - 7); ctx.lineTo(bx, yBlk + Fw * fScale); ctx.lineTo(bx + 4, yBlk + Fw * fScale - 7); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("mg = " + Fw.toFixed(1) + " N", bx + 6, yBlk + Fw * fScale + 4);

out.note = "x0 = " + x0.toFixed(4) + " m,  T = " + (2 * Math.PI / w).toFixed(3) + " s,  f = " + (w / (2 * Math.PI)).toFixed(3) + " Hz,  v_max = " + (A * w).toFixed(3) + " m/s";

var kPar = p.k1 + p.k2;
var kSer = 1 / (1 / p.k1 + 1 / p.k2);
var xPar = p.load / kPar;
var xSer = p.load / kSer;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

function coil(x1, y1, x2, y2, n, col) {
  ctx.strokeStyle = col;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  for (var i = 1; i <= n; i++) {
    var xx = x1 + (x2 - x1) * i / n;
    var yy = y1 + (y2 - y1) * i / n + (i % 2 === 0 ? -9 : 9) * (i === n ? 0 : 1);
    ctx.lineTo(xx, yy);
  }
  ctx.lineTo(x2, y2);
  ctx.stroke();
}

// ---- parallel, left half ----
var wallX = W * 0.06;
var topY = H * 0.20;
var gap = H * 0.14;
var restLen = W * 0.20;
var sc = (W * 0.10) / 0.5;
var blockX = wallX + restLen + Math.min(xPar * sc, W * 0.10);

ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 7, topY - gap - 14, 7, 2 * gap + 28);
coil(wallX, topY - gap, blockX - 14, topY - gap, 10, C.accent);
coil(wallX, topY + gap, blockX - 14, topY + gap, 10, C.accent);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(blockX - 14, topY - gap - 14, 28, 2 * gap + 28, 4); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("PARALLEL", wallX, topY - gap - 26);
ctx.fillStyle = C.accent;
ctx.fillText("k1", wallX + restLen * 0.4, topY - gap - 14);
ctx.fillText("k2", wallX + restLen * 0.4, topY + gap + 24);
ctx.fillStyle = C.figure;
ctx.fillText("same x, forces add", wallX, topY + gap + 44);
ctx.fillText("k = k1 + k2 = " + kPar.toFixed(0) + " N/m", wallX, topY + gap + 60);
ctx.fillText("x = " + xPar.toFixed(4) + " m", wallX, topY + gap + 76);

// ---- series, right half ----
var wx = W * 0.56;
var sy = H * 0.20;
var seg = W * 0.13;
var stretchPx = Math.min(xSer * sc, W * 0.10);
var midX = wx + seg + stretchPx * (p.k2 / (p.k1 + p.k2));
var endX = wx + 2 * seg + stretchPx;

ctx.fillStyle = C.faint;
ctx.fillRect(wx - 7, sy - 20, 7, 40);
coil(wx, sy, midX - 4, sy, 8, C.accent);
coil(midX + 4, sy, endX - 14, sy, 8, C.accent);
ctx.fillStyle = C.rule;
ctx.beginPath(); ctx.arc(midX, sy, 4, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(endX - 14, sy - 16, 28, 32, 4); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("SERIES", wx, sy - 34);
ctx.fillStyle = C.accent;
ctx.fillText("k1", wx + seg * 0.4, sy - 16);
ctx.fillText("k2", midX + seg * 0.4, sy - 16);
ctx.fillStyle = C.figure;
ctx.fillText("same F, stretches add", wx, sy + 44);
ctx.fillText("1/k = 1/k1 + 1/k2", wx, sy + 60);
ctx.fillText("k = " + kSer.toFixed(1) + " N/m,  x = " + xSer.toFixed(4) + " m", wx, sy + 76);

// pull arrows
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(blockX + 16, topY); ctx.lineTo(blockX + 46, topY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(blockX + 40, topY - 4); ctx.lineTo(blockX + 46, topY); ctx.lineTo(blockX + 40, topY + 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(endX + 16, sy); ctx.lineTo(endX + 46, sy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(endX + 40, sy - 4); ctx.lineTo(endX + 46, sy); ctx.lineTo(endX + 40, sy + 4); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("F", blockX + 30, topY - 8);
ctx.fillText("F", endX + 30, sy - 8);

out.note = "F = " + p.load.toFixed(0) + " N:  parallel k = " + kPar.toFixed(0) + " N/m (x = " + xPar.toFixed(4) + " m),  series k = " + kSer.toFixed(1) + " N/m (x = " + xSer.toFixed(4) + " m)";

var g = 9.8;
var h = p.h;
var w = Math.sqrt(p.k / p.mass);
var x0 = p.mass * g / p.k;
var v0 = Math.sqrt(2 * g * h);
var amp = Math.sqrt(x0 * x0 + (v0 * v0) / (w * w));
var dmax = x0 + amp;
var tf = Math.sqrt(2 * h / g);
var tPeak = (Math.PI - Math.atan2(v0, x0 * w)) / w;
var tc = 2 * tPeak;
var cycle = 2 * tf + tc + 0.4;
var tt = t % cycle;

var drop, comp;
if (tt < tf) { drop = 0.5 * g * tt * tt; comp = 0; }
else if (tt < tf + tc) {
  var tau = tt - tf;
  var u = -x0 * Math.cos(w * tau) + (v0 / w) * Math.sin(w * tau);
  comp = x0 + u;
  drop = h + comp;
} else {
  var tr = Math.min(tt - tf - tc, tf);
  drop = h - 0.5 * g * (tf - tr) * (tf - tr);
  if (drop < 0) drop = 0;
  comp = 0;
}

var span = h + dmax + 0.04;
var pxPerM = (H * 0.58) / span;
var cx = W * 0.40;
var groundY = H * 0.88;
var restTop = groundY - (dmax * pxPerM + H * 0.10);
var springTop = restTop + comp * pxPerM;
var blockBottom = comp > 0 ? springTop : restTop - (h - drop) * pxPerM;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

// ground
ctx.fillStyle = C.faint;
ctx.fillRect(cx - W * 0.18, groundY, W * 0.36, 7);

// spring
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(cx, groundY);
var n = 12;
for (var i = 1; i <= n; i++) {
  var yy = groundY + (springTop - groundY) * i / n;
  var dx = (i % 2 === 0 ? -13 : 13) * (i === n ? 0 : 1);
  ctx.lineTo(cx + dx, yy);
}
ctx.lineTo(cx, springTop);
ctx.stroke();

// markers
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx - W * 0.24, restTop); ctx.lineTo(cx + W * 0.30, restTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx - W * 0.24, restTop - h * pxPerM); ctx.lineTo(cx + W * 0.30, restTop - h * pxPerM); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx - W * 0.24, restTop + dmax * pxPerM); ctx.lineTo(cx + W * 0.30, restTop + dmax * pxPerM); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("release point", cx + W * 0.12, restTop - h * pxPerM - 4);
ctx.fillText("spring top, relaxed", cx + W * 0.12, restTop - 4);
ctx.fillText("lowest point", cx + W * 0.12, restTop + dmax * pxPerM - 4);

// height arrow
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
var ax = cx - W * 0.22;
ctx.beginPath(); ctx.moveTo(ax, restTop - h * pxPerM); ctx.lineTo(ax, restTop); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("h", ax - 12, (2 * restTop - h * pxPerM) / 2);
ctx.beginPath(); ctx.moveTo(ax, restTop); ctx.lineTo(ax, restTop + dmax * pxPerM); ctx.stroke();
ctx.fillText("d", ax - 12, restTop + dmax * pxPerM / 2);

// block
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(cx - 20, blockBottom - 32, 40, 32, 4); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("m", cx - 5, blockBottom - 12);

out.note = "impact speed v = " + v0.toFixed(3) + " m/s,  static sag x0 = " + x0.toFixed(4) + " m,  max compression d = " + dmax.toFixed(4) + " m,  energy stored = " + (0.5 * p.k * dmax * dmax).toFixed(3) + " J";
